21	// DEVDESK-308 (IS-14), step 1: which picker entries can only list cached
22	// content. A Nexus group, its discovered members and an entry declaring
23	// `parent:` towards a Nexus group do (Q-B ii); nothing else does.
24	func TestListsCacheOnly(t *testing.T) {
25		harbor := config.RegistryItem{Slug: "hb", Kind: config.KindGroup, Provider: config.ProviderHarbor, URL: "harbor.example.com"}
26		generic := config.RegistryItem{Slug: "gn", Kind: config.KindGroup, Provider: config.ProviderGeneric, URL: "reg.example.com"}
27		bySlug := map[string]config.RegistryItem{"nx": nexusGroup(), "hb": harbor, "gn": generic}
28	
29		tests := []struct {
30			name string
31			reg  config.RegistryItem
32			want bool
33		}{
34			{"nexus group", nexusGroup(), true},
35			{"declared parent to nexus group", config.RegistryItem{Slug: "m", Kind: config.KindRegistry, Parent: "nx"}, true},
36			{"harbor group", harbor, false},
37			{"generic group", generic, false},
38			{"nexus registry without parent", config.RegistryItem{Slug: "n2", Kind: config.KindRegistry, Provider: config.ProviderNexus}, false},
39			{"docker hub", config.RegistryItem{Slug: "hub", Kind: config.KindRegistry, URL: "docker.io"}, false},
40			{"parent to generic group", config.RegistryItem{Slug: "m2", Kind: config.KindRegistry, Parent: "gn"}, false},
41			{"parent to harbor group", config.RegistryItem{Slug: "m3", Kind: config.KindRegistry, Parent: "hb"}, false},
42			{"parent to unknown slug", config.RegistryItem{Slug: "m4", Kind: config.KindRegistry, Parent: "zz"}, false},
43		}
44		for _, tt := range tests {
45			t.Run(tt.name, func(t *testing.T) {
46				if got := listsCacheOnly(tt.reg, bySlug); got != tt.want {
47					t.Fatalf("listsCacheOnly(%+v) = %v, want %v", tt.reg, got, tt.want)
48				}
49			})
50		}
51	}
