53	func TestBuildEntriesFlagsCachedOnly(t *testing.T) {
54		harbor := config.RegistryItem{Slug: "hb", Kind: config.KindGroup, Provider: config.ProviderHarbor, URL: "harbor.example.com", Alias: "hb"}
55		generic := config.RegistryItem{Slug: "gn", Kind: config.KindGroup, Provider: config.ProviderGeneric, URL: "reg.example.com", Alias: "gn"}
56		nexusPlain := config.RegistryItem{Slug: "n2", Kind: config.KindRegistry, Provider: config.ProviderNexus, URL: "n2.example.com", Alias: "n2"}
57		hub := config.RegistryItem{Slug: "hub", Kind: config.KindRegistry, URL: "docker.io", Alias: "hub"}
58		declared := config.RegistryItem{Slug: "decl", Kind: config.KindRegistry, Parent: "nx", URL: "decl.example.com", Alias: "decl"}
59		declaredGeneric := config.RegistryItem{Slug: "declg", Kind: config.KindRegistry, Parent: "gn", URL: "declg.example.com", Alias: "declg"}
60	
61		member := func(a string) cache.RegistryGroupMember {
62			return cache.RegistryGroupMember{Alias: a, URL: a + ".example.com"}
63		}
64		regs := []config.RegistryItem{nexusGroup(), harbor, generic, nexusPlain, hub, declared, declaredGeneric}
65	
66		tests := []struct {
67			name   string
68			groups map[string]cache.RegistryGroupEntry
69			want   map[string]bool // Alias -> cachedOnly
70		}{
71			{
72				name:   "nothing discovered",
73				groups: nil,
74				want: map[string]bool{
75					"nx": true, "hb": false, "gn": false, "n2": false,
76					"hub": false, "decl": true, "declg": false,
77				},
78			},
79			{
80				name: "members discovered",
81				groups: map[string]cache.RegistryGroupEntry{
82					"nx": {Members: []cache.RegistryGroupMember{member("nx-a"), member("nx-b")}},
83					"hb": {Members: []cache.RegistryGroupMember{member("hb-a")}},
84					"gn": {Members: []cache.RegistryGroupMember{member("gn-a")}},
85				},
86				want: map[string]bool{
87					"nx-a": true, "nx-b": true, "hb-a": false, "gn-a": false,
88					"n2": false, "hub": false, "decl": true, "declg": false,
89				},
90			},
91		}
92		for _, tt := range tests {
93			t.Run(tt.name, func(t *testing.T) {
94				b := newRegistryBrowser(regs, tt.groups, nil, 120, 40)
95				got := map[string]bool{}
96				for _, e := range b.entries {
97					got[e.Alias] = e.cachedOnly
98				}
99				if len(got) != len(tt.want) {
100					t.Fatalf("entries = %v, want aliases %v", got, tt.want)
101				}
102				for alias, want := range tt.want {
103					g, ok := got[alias]
104					if !ok || g != want {
105						t.Errorf("entry %q cachedOnly = %v (present %v), want %v", alias, g, ok, want)
106					}
107				}
108			})
109		}
110	}
