249	// checkGroupUnit checks what a unit is: the group's own address, resolved the way
250	// the group itself would be (its credentials, its key), marked with the label.
251	func checkGroupUnit(t *testing.T, unit browserRegistryEntry, g config.RegistryItem, input []browserRegistryEntry) {
252		t.Helper()
253		var first browserRegistryEntry
254		for _, e := range input {
255			if e.ParentSlug == g.Slug {
256				first = e
257				break
258			}
259		}
260		if unit.key != g.Slug || unit.Slug != g.Slug {
261			t.Errorf("unit key = %q, Slug = %q, want both %q", unit.key, unit.Slug, g.Slug)
262		}
263		if unit.URL != g.URL || unit.repoPrefix != g.RepoPrefix {
264			t.Errorf("unit address = (%q, %q), want the group's (%q, %q)", unit.URL, unit.repoPrefix, g.URL, g.RepoPrefix)
265		}
266		// The group-level `r` stop (resultFilter.groupSlug) must still take the unit's rows.
267		if unit.ParentSlug != g.Slug || unit.ParentAlias != "" {
268			t.Errorf("unit ParentSlug = %q, ParentAlias = %q, want %q and none", unit.ParentSlug, unit.ParentAlias, g.Slug)
269		}
270		if unit.authMode != first.authMode || unit.cachedOnly != first.cachedOnly {
271			t.Errorf("unit authMode = %q, cachedOnly = %v, want its members' (%q, %v)", unit.authMode, unit.cachedOnly, first.authMode, first.cachedOnly)
272		}
273		if unit.catalogUnderPrefix {
274			t.Error("a unit at the group's own address is read at the root, never under a prefix")
275		}
276		if got, want := entryAlias(unit), groupUnitLabel(browserAlias(g)); got != want {
277			t.Errorf("unit label = %q, want %q", got, want)
278		}
279	}
