291	// Criterion 6: a member whose own catalog answers an error is that member's
292	// problem. 404, 401, 403 and 405 are a refusal (this Nexus does not serve a
293	// catalog there, or not to this account); 5xx and 429 are a failure. The other
294	// member keeps its verdict and its rows, the root catalog is never asked, and
295	// the journal says why without the URL (a 401 without a Bearer challenge reads
296	// as an unexpected challenge, not as a status).
297	func TestAMemberWhoseCatalogAnswersAnErrorDoesNotSpoilTheOthers(t *testing.T) {
298		tests := []struct {
299			status  int
300			verdict imagesearch.Verdict
301			header  string // the header line that names the member
302			level   string // the journal level of that verdict
303			cause   string // what the journal says about it
304		}{
305			{http.StatusNotFound, imagesearch.VerdictRefused, "Refused", "INFO", "404"},
306			{http.StatusUnauthorized, imagesearch.VerdictRefused, "Refused", "INFO", "auth challenge"},
307			{http.StatusForbidden, imagesearch.VerdictRefused, "Refused", "INFO", "403"},
308			{http.StatusMethodNotAllowed, imagesearch.VerdictRefused, "Refused", "INFO", "405"},
309			{http.StatusServiceUnavailable, imagesearch.VerdictFailed, "Failed", "ERROR", "503"},
310			{http.StatusInternalServerError, imagesearch.VerdictFailed, "Failed", "ERROR", "500"},
311			{http.StatusTooManyRequests, imagesearch.VerdictFailed, "Failed", "ERROR", "429"},
312		}
313		for _, tt := range tests {
314			t.Run(fmt.Sprint(tt.status), func(t *testing.T) {
315				srv := newPathServer(t, map[string]int{"/v2/a/_catalog": tt.status, "/v2/b/_catalog": http.StatusOK})
316				withImageSearcher(t, wiredLikeProduction(srv.Server))
317				logs := captureLog(t)
318	
319				m := runLot(t, nexusMembersModel(t, srv.URL, "a", "b"), "nginx", 2)
320	
321				keyA, keyB := memberKey("nx", srv.URL, "a"), memberKey("nx", srv.URL, "b")
322				wantVerdict(t, m, keyA, tt.verdict)
323				wantVerdict(t, m, keyB, imagesearch.VerdictOK)
324				want := []string{keyB + ":b/nginx", keyB + ":b/nginx-x"}
325				if got := rowsOf(m); !slices.Equal(sorted(got), want) {
326					t.Errorf("rows = %v, want only b's: %v", got, want)
327				}
328				if n := srv.requests("/v2/_catalog"); n != 0 {
329					t.Errorf("the root /v2/_catalog got %d requests, want 0", n)
330				}
331				if n := srv.requests("/v2/b/_catalog"); n != 1 {
332					t.Errorf("/v2/b/_catalog got %d requests, want 1", n)
333				}
334				if n := srv.requests("/v2/a/_catalog"); n == 0 {
335					t.Error("/v2/a/_catalog was never asked")
336				}
337	
338				_, vals := headerLines(m)
339				if !strings.Contains(vals[tt.header], "nx/a") || strings.Contains(vals[tt.header], "nx/b") {
340					t.Errorf("%s = %q, want nx/a and not nx/b", tt.header, vals[tt.header])
341				}
342				if !strings.Contains(vals["Cached only"], "nx/b") {
343					t.Errorf("Cached only = %q, want it to list nx/b", vals["Cached only"])
344				}
345	
346				// The cause is in the journal: readable (the status), with no URL.
347				out := logs.String()
348				line := tt.level + " [oci_resources] image search on nx/a:"
349				if !strings.Contains(out, line) || !strings.Contains(out, tt.cause) {
350					t.Errorf("journal = %q, want %q and the cause %q", out, line, tt.cause)
351				}
352				u, _ := url.Parse(srv.URL)
353				for _, leak := range []string{u.Host, "_catalog", "http://"} {
354					if strings.Contains(out, leak) {
355						t.Errorf("the journal holds %q: %q", leak, out)
356					}
357				}
358			})
359		}
360	}

