242	// pathServer answers the catalog of each member path with a status and counts
243	// every request it gets, by path. A path it was not told about answers 404 and is
244	// counted all the same, so a request to the root shows.
245	type pathServer struct {
246		*httptest.Server
247		mu     sync.Mutex
248		counts map[string]int
249	}
250	
251	func newPathServer(t *testing.T, status map[string]int) *pathServer {
252		t.Helper()
253		ps := &pathServer{counts: map[string]int{}}
254		ps.Server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
255			ps.mu.Lock()
256			ps.counts[r.URL.Path]++
257			ps.mu.Unlock()
258			code, known := status[r.URL.Path]
259			if !known {
260				http.NotFound(w, r)
261				return
262			}
263			if code != http.StatusOK {
264				http.Error(w, "refused by the fake", code)
265				return
266			}
267			w.Header().Set("Content-Type", "application/json")
268			_, _ = w.Write([]byte(`{"repositories":["nginx","nginx-x","other"]}`))
269		}))
270		t.Cleanup(ps.Close)
271		return ps
272	}
273	
274	func (p *pathServer) requests(path string) int {
275		p.mu.Lock()
276		defer p.mu.Unlock()
277		return p.counts[path]
278	}
