122			{"refused", []string{"a"}, map[string]imagesearch.Outcome{"a": refused}, true, nil, searchSummary{Refused: []string{"a"}}},
123			{"ok partial", []string{"a"}, map[string]imagesearch.Outcome{"a": okPartial}, true, nil, searchSummary{Partial: []string{"a"}}},
124			{"no result", []string{"a"}, map[string]imagesearch.Outcome{"a": none}, true, nil, searchSummary{NoResult: []string{"a"}}},
125			{"no result and partial is both", []string{"a"}, map[string]imagesearch.Outcome{"a": nonePartial}, true, nil,
126				searchSummary{NoResult: []string{"a"}, Partial: []string{"a"}}},
127			{"skipped is only skipped", []string{"a"}, map[string]imagesearch.Outcome{"a": skipped}, true, nil,
128				searchSummary{Skipped: []string{"a"}}},
129			{"names follow the keys, not the map", []string{"z", "m", "a"},
130				map[string]imagesearch.Outcome{"a": refused, "m": refused, "z": refused}, true, nil,
131				searchSummary{Refused: []string{"z", "m", "a"}}},
