106				t.Errorf("rows under %q = %d in %v, want 1 (own prefix only)", want, n, rows)
107			}
108		}
109		for _, r := range rows {
110			if strings.Contains(r, ":other/") {
111				t.Errorf("row %q is outside every entry prefix", r)
