22	
23	func TestFitNames(t *testing.T) {
24		tests := []struct {
25			name   string
26			names  []string
27			suffix string
28			width  int
29			want   string
30		}{
31			{"everything fits", []string{"dhi.io", "nexus-prod"}, "", 18, "dhi.io, nexus-prod"},
32			{"one name and a count", []string{"dhi.io", "nexus-prod"}, "", 10, "dhi.io, +1"},
33			{"only a count", []string{"dhi.io", "nexus-prod"}, "", 9, "+2"},
34			{"keeps as many names as fit", []string{"a", "b", "cccccc"}, "", 8, "a, b, +1"},
35			{"one fewer name", []string{"a", "b", "cccccc"}, "", 7, "a, +2"},
36			{"suffix fits", []string{"nexus-prod"}, skippedHint, 40, "nexus-prod (type 2+ characters)"},
37			{"suffix dropped before the name (V3)", []string{"nexus-prod"}, skippedHint, 20, "nexus-prod"},
38			{"count and suffix", []string{"p1", "p2"}, skippedHint, 25, "+2 (type 2+ characters)"},
39			{"count alone when nothing else fits", []string{"nexus-prod"}, skippedHint, 5, "+1"},
40			{"width 1 overflows with the count", []string{"a", "b"}, "", 1, "+2"},
41			{"width 0 overflows with the count", []string{"a", "b", "c"}, "", 0, "+3"},
42			{"no width limit shows all", []string{"a", "b", "c"}, "", noWidthLimit, "a, b, c"},
43			{"no width limit keeps the suffix", []string{"a"}, skippedHint, noWidthLimit, "a (type 2+ characters)"},
44			{"nil names", nil, "", 40, ""},
45			{"nil names with a suffix", nil, skippedHint, 40, ""},
46			{"wide characters count for 2 cells", []string{"日本"}, "", 4, "日本"},
47			{"wide characters do not fit in 3", []string{"日本"}, "", 3, "+1"},
48		}
49		for _, tt := range tests {
50			t.Run(tt.name, func(t *testing.T) {
51				if got := fitNames(tt.names, tt.suffix, tt.width); got != tt.want {
52					t.Errorf("fitNames(%v, %q, %d) = %q, want %q", tt.names, tt.suffix, tt.width, got, tt.want)
53				}
54			})
55		}
56	}
