65	// Property: an abbreviation always says how many names it hides, and it fits
66	// whenever a bare "+N" does.
67	func TestFitNamesNeverHidesACount(t *testing.T) {
68		pool := []string{"hub", "prod", "dhi.io", "nexus-prod", "third", "日本語"}
69		for _, suffix := range []string{"", skippedHint} {
70			for n := 1; n <= len(pool); n++ {
71				names := pool[:n]
72				for width := 2; width <= 60; width++ {
73					out := fitNames(names, suffix, width)
74					if ansi.StringWidth(out) > width {
75						t.Errorf("fitNames(%v, %q, %d) = %q is %d cells wide", names, suffix, width, out, ansi.StringWidth(out))
76					}
77					list := strings.TrimSuffix(out, suffix)
78					parts := strings.Split(list, ", ")
79					shown, hidden := len(parts), 0
80					if last := parts[len(parts)-1]; strings.HasPrefix(last, "+") {
81						c, err := strconv.Atoi(strings.TrimPrefix(last, "+"))
82						if err != nil {
83							t.Errorf("fitNames(%v, %q, %d) = %q: bad count %q", names, suffix, width, out, last)
84							continue
85						}
86						shown, hidden = len(parts)-1, c
87					}
88					if shown+hidden != n {
89						t.Errorf("fitNames(%v, %q, %d) = %q shows %d and hides %d, want %d in all",
90							names, suffix, width, out, shown, hidden, n)
91					}
92				}
93			}
94		}
95	}
