99	func TestSummarizeSearch(t *testing.T) {
100		ok := imagesearch.Outcome{Verdict: imagesearch.VerdictOK}
101		okPartial := imagesearch.Outcome{Verdict: imagesearch.VerdictOK, Partial: true}
102		none := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult}
103		nonePartial := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Partial: true}
104		skipped := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Skipped: true}
105		refused := imagesearch.Outcome{Verdict: imagesearch.VerdictRefused}
106		failed := imagesearch.Outcome{Verdict: imagesearch.VerdictFailed}
107	
108		tests := []struct {
109			name     string
110			keys     []string
111			outcomes map[string]imagesearch.Outcome
112			live     bool
113			cached   []string // keys the lot's cachedOnly predicate accepts
114			want     searchSummary
115		}{
116			{"no keys", nil, nil, true, nil, searchSummary{}},
117			{"ok without a mark appears nowhere", []string{"a"}, map[string]imagesearch.Outcome{"a": ok}, true, nil, searchSummary{}},
118			{"no outcome in a live lot is pending", []string{"a", "b"}, nil, true, nil, searchSummary{Pending: 2}},
119			{"no outcome in an abandoned lot is interrupted", []string{"a", "b"},
120				map[string]imagesearch.Outcome{"a": ok}, false, nil, searchSummary{Interrupted: []string{"b"}}},
121			{"failed", []string{"a"}, map[string]imagesearch.Outcome{"a": failed}, true, nil, searchSummary{Failed: []string{"a"}}},
122			{"refused", []string{"a"}, map[string]imagesearch.Outcome{"a": refused}, true, nil, searchSummary{Refused: []string{"a"}}},
123			{"ok partial", []string{"a"}, map[string]imagesearch.Outcome{"a": okPartial}, true, nil, searchSummary{Partial: []string{"a"}}},
124			{"no result", []string{"a"}, map[string]imagesearch.Outcome{"a": none}, true, nil, searchSummary{NoResult: []string{"a"}}},
125			{"no result and partial is both", []string{"a"}, map[string]imagesearch.Outcome{"a": nonePartial}, true, nil,
126				searchSummary{NoResult: []string{"a"}, Partial: []string{"a"}}},
127			{"skipped is only skipped", []string{"a"}, map[string]imagesearch.Outcome{"a": skipped}, true, nil,
128				searchSummary{Skipped: []string{"a"}}},
129			{"names follow the keys, not the map", []string{"z", "m", "a"},
130				map[string]imagesearch.Outcome{"a": refused, "m": refused, "z": refused}, true, nil,
131				searchSummary{Refused: []string{"z", "m", "a"}}},
132			{"a mix", []string{"hub", "prod", "dev", "slow", "third"},
133				map[string]imagesearch.Outcome{"hub": ok, "prod": refused, "dev": failed, "slow": okPartial}, true, nil,
134				searchSummary{Pending: 1, Failed: []string{"dev"}, Refused: []string{"prod"}, Partial: []string{"slow"}}},
135			// DEVDESK-308 (IS-14): a registry that only lists cached content gets the
136			// Cached only line; a no-result there means "absent from the cache" and
137			// leaves No result, which then means "absent from the registry".
138			{"cached ok is listed", []string{"a"}, map[string]imagesearch.Outcome{"a": ok}, true, []string{"a"},
139				searchSummary{CachedOnly: []string{"a"}}},
140			{"cached no result is marked and leaves No result", []string{"a"}, map[string]imagesearch.Outcome{"a": none}, true, []string{"a"},
141				searchSummary{CachedOnly: []string{"a" + cachedNoResultMark}}},
142			{"cached ok partial is on both lines", []string{"a"}, map[string]imagesearch.Outcome{"a": okPartial}, true, []string{"a"},
143				searchSummary{Partial: []string{"a"}, CachedOnly: []string{"a"}}},
144			{"cached no result and partial is Partial and marked", []string{"a"}, map[string]imagesearch.Outcome{"a": nonePartial}, true, []string{"a"},
145				searchSummary{Partial: []string{"a"}, CachedOnly: []string{"a" + cachedNoResultMark}}},
146			{"cached failed keeps only Failed", []string{"a"}, map[string]imagesearch.Outcome{"a": failed}, true, []string{"a"},
147				searchSummary{Failed: []string{"a"}}},
148			{"cached refused keeps only Refused", []string{"a"}, map[string]imagesearch.Outcome{"a": refused}, true, []string{"a"},
149				searchSummary{Refused: []string{"a"}}},
150			{"cached skipped keeps only Skipped", []string{"a"}, map[string]imagesearch.Outcome{"a": skipped}, true, []string{"a"},
151				searchSummary{Skipped: []string{"a"}}},
152			{"cached pending stays pending", []string{"a"}, nil, true, []string{"a"}, searchSummary{Pending: 1}},
153			{"cached interrupted stays interrupted", []string{"a"}, nil, false, []string{"a"}, searchSummary{Interrupted: []string{"a"}}},
154			{"an unconcerned registry is unchanged", []string{"a", "b", "c"},
155				map[string]imagesearch.Outcome{"a": ok, "b": none, "c": none}, true, []string{"a"},
156				searchSummary{CachedOnly: []string{"a"}, NoResult: []string{"b", "c"}}},
157			{"cached names follow the keys", []string{"z", "m", "a"},
158				map[string]imagesearch.Outcome{"a": ok, "m": none, "z": ok}, true, []string{"a", "m", "z"},
159				searchSummary{CachedOnly: []string{"z", "m" + cachedNoResultMark, "a"}}},
160		}
161		label := func(k string) string { return "L:" + k }
162		for _, tt := range tests {
163			t.Run(tt.name, func(t *testing.T) {
164				concerned := func(k string) bool { return slices.Contains(tt.cached, k) }
165				got := summarizeSearch(tt.keys, tt.outcomes, tt.live, label, concerned)
166				// Names carry the label, not the key.
167				want := tt.want
168				for _, p := range []*[]string{&want.Interrupted, &want.Failed, &want.Refused, &want.Partial, &want.CachedOnly, &want.NoResult, &want.Skipped} {
169					for i, k := range *p {
170						(*p)[i] = "L:" + k
171					}
172				}
173				if !reflect.DeepEqual(got, want) {
174					t.Errorf("summarizeSearch = %+v, want %+v", got, want)
175				}
176			})
177		}
178	}
