	proxy := map[string]nexusRole{"a": nexusRoleProxy}
	hosted := map[string]nexusRole{"a": nexusRoleHosted}
	one := func(oc imagesearch.Outcome) map[string]imagesearch.Outcome { return map[string]imagesearch.Outcome{"a": oc} }

	tests := []struct {
		name     string
		keys     []string
		outcomes map[string]imagesearch.Outcome
		live     bool
		roles    map[string]nexusRole // role by key; a key not in it is unknown
		want     summaryClasses
	}{
		{"no keys", nil, nil, true, nil, summaryClasses{}},
		{"ok without a mark appears nowhere", []string{"a"}, one(ok), true, nil, summaryClasses{}},
		{"no outcome in a live lot is pending", []string{"a", "b"}, nil, true, nil, summaryClasses{Pending: 2}},
		{"no outcome in an abandoned lot is interrupted", []string{"a", "b"},
			map[string]imagesearch.Outcome{"a": ok}, false, nil, summaryClasses{Interrupted: []string{"b"}}},
		{"failed", []string{"a"}, one(failed), true, nil, summaryClasses{Failed: []string{"a"}}},
		{"refused", []string{"a"}, one(refused), true, nil, summaryClasses{Refused: []string{"a"}}},
		{"ok partial", []string{"a"}, one(okPartial), true, nil, summaryClasses{Partial: []string{"a"}}},
		{"no result", []string{"a"}, one(none), true, nil, summaryClasses{NoResult: []string{"a"}}},
		{"no result and partial is both", []string{"a"}, one(nonePartial), true, nil,
			summaryClasses{NoResult: []string{"a"}, Partial: []string{"a"}}},
		{"skipped is only skipped", []string{"a"}, one(skipped), true, nil, summaryClasses{Skipped: []string{"a"}}},
		{"names follow the keys, not the map", []string{"z", "m", "a"},
			map[string]imagesearch.Outcome{"a": refused, "m": refused, "z": refused}, true, nil,
			summaryClasses{Refused: []string{"z", "m", "a"}}},
		{"a mix", []string{"hub", "prod", "dev", "slow", "third"},
