		{"group ok is listed", []string{"a"}, one(ok), true, group, summaryClasses{MayOmit: []string{"a"}}},
		{"group no result is marked and leaves No result", []string{"a"}, one(none), true, group,
			summaryClasses{MayOmit: []string{"a" + noResultMark}}},
		{"group ok partial is on both lines", []string{"a"}, one(okPartial), true, group,
			summaryClasses{Partial: []string{"a"}, MayOmit: []string{"a"}}},
		{"group no result and partial is Partial and marked", []string{"a"}, one(nonePartial), true, group,
			summaryClasses{Partial: []string{"a"}, MayOmit: []string{"a" + noResultMark}}},
		{"group failed is on Failed and on May omit, without the mark", []string{"a"}, one(failed), true, group,
			summaryClasses{Failed: []string{"a"}, MayOmit: []string{"a"}}},
		{"group refused is on Refused and on May omit, without the mark", []string{"a"}, one(refused), true, group,
			summaryClasses{Refused: []string{"a"}, MayOmit: []string{"a"}}},
		{"group skipped keeps only Skipped", []string{"a"}, one(skipped), true, group, summaryClasses{Skipped: []string{"a"}}},
		{"group pending stays pending", []string{"a"}, nil, true, group, summaryClasses{Pending: 1}},
		{"group interrupted stays interrupted", []string{"a"}, nil, false, group, summaryClasses{Interrupted: []string{"a"}}},

		// A proxy only when it failed or was refused: its upstream answers or it does not.
		{"proxy ok is not mentioned", []string{"a"}, one(ok), true, proxy, summaryClasses{}},
		{"proxy no result is a plain No result", []string{"a"}, one(none), true, proxy, summaryClasses{NoResult: []string{"a"}}},
		{"proxy ok partial is only Partial", []string{"a"}, one(okPartial), true, proxy, summaryClasses{Partial: []string{"a"}}},
		{"proxy failed is on Failed and on May omit", []string{"a"}, one(failed), true, proxy,
			summaryClasses{Failed: []string{"a"}, MayOmit: []string{"a"}}},
		{"proxy refused is on Refused and on May omit", []string{"a"}, one(refused), true, proxy,
			summaryClasses{Refused: []string{"a"}, MayOmit: []string{"a"}}},
		{"proxy skipped keeps only Skipped", []string{"a"}, one(skipped), true, proxy, summaryClasses{Skipped: []string{"a"}}},

		// A hosted repository holds what it holds.
		{"hosted failed keeps only Failed", []string{"a"}, one(failed), true, hosted, summaryClasses{Failed: []string{"a"}}},
		{"hosted refused keeps only Refused", []string{"a"}, one(refused), true, hosted, summaryClasses{Refused: []string{"a"}}},
		{"hosted no result is a plain No result", []string{"a"}, one(none), true, hosted, summaryClasses{NoResult: []string{"a"}}},
		{"hosted ok is not mentioned", []string{"a"}, one(ok), true, hosted, summaryClasses{}},

		{"an unconcerned registry is unchanged", []string{"a", "b", "c"},
			map[string]imagesearch.Outcome{"a": ok, "b": none, "c": none}, true, map[string]nexusRole{"a": nexusRoleGroup},
			summaryClasses{MayOmit: []string{"a"}, NoResult: []string{"b", "c"}}},
		{"mentioned names follow the keys", []string{"z", "m", "a"},
			map[string]imagesearch.Outcome{"a": failed, "m": none, "z": ok}, true,
			map[string]nexusRole{"z": nexusRoleGroup, "m": nexusRoleGroup, "a": nexusRoleProxy},
			summaryClasses{Failed: []string{"a"}, MayOmit: []string{"z", "m" + noResultMark, "a"}}},
	}
	label := func(k string) string { return "L:" + k }
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			role := func(k string) nexusRole { return tt.roles[k] }
			got := classesOf(summarize(tt.keys, tt.outcomes, tt.live, label, role))
			// Names carry the label, not the key.
			want := tt.want
			for _, p := range []*[]string{&want.Interrupted, &want.Failed, &want.Refused, &want.Partial, &want.MayOmit, &want.NoResult, &want.Skipped} {
				for i, k := range *p {
					(*p)[i] = "L:" + k
				}
			}
			if !reflect.DeepEqual(got, want) {
				t.Errorf("summarizeSearch = %+v, want %+v", got, want)
			}
		})
	}
}

